diff --git a/repro/no-useless-assignment-update.js b/repro/no-useless-assignment-update.js
new file mode 100644
index 0000000..d89e001
--- /dev/null
+++ b/repro/no-useless-assignment-update.js
@@ -0,0 +1,40 @@
+"use strict";
+
+// Reproduction for: no-useless-assignment false positive when the result of
+// ++i / --i (prefix UpdateExpression) is used as a value.
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+const config = { rules: { "no-useless-assignment": "error" } };
+
+const cases = [
+	// Reported cases: value of the update expression is the arrow's return value.
+	{ code: "[1, 2, 3].map(i => ++i);", expectErrors: 0 },
+	{ code: "[1, 2, 3].map(i => --i);", expectErrors: 0 },
+	// Control: equivalent non-mutating forms (no error, per report).
+	{ code: "[1, 2, 3].map(i => i + 1);", expectErrors: 0 },
+	{ code: "[1, 2, 3].map(i => i - 1);", expectErrors: 0 },
+	// Same shape without arrow shorthand: result used by return / call arg / binding.
+	{ code: "function f(i) { return ++i; }", expectErrors: 0 },
+	{ code: "function f(i) { console.log(++i); }", expectErrors: 0 },
+	{ code: "function f(i) { const j = ++i; return j; }", expectErrors: 0 },
+	// Analogous compound assignment used as value.
+	{ code: "[1, 2, 3].map(i => i += 1);", expectErrors: 0 },
+	// Genuine useless assignment, for contrast (postfix value is the old value,
+	// so the stored increment is really never read).
+	{ code: "function f(i) { return i++; }", expectErrors: 1 },
+];
+
+let mismatches = 0;
+for (const { code, expectErrors } of cases) {
+	const msgs = linter.verify(code, config);
+	const ok = msgs.length === expectErrors;
+	if (!ok) mismatches++;
+	console.log(`${ok ? "ok  " : "BUG "} expected ${expectErrors}, got ${msgs.length}: ${code}`);
+	for (const m of msgs) {
+		console.log(`       ${m.line}:${m.column} [${m.ruleId}] ${m.message}`);
+	}
+}
+
+console.log(`\n${mismatches} case(s) differ from expectation.`);
+process.exitCode = mismatches ? 1 : 0;
diff --git a/repro/report.js b/repro/report.js
new file mode 100644
index 0000000..a9c9311
--- /dev/null
+++ b/repro/report.js
@@ -0,0 +1,9 @@
+/* eslint no-useless-assignment: "error" */
+
+// shows error
+[1, 2, 3].map(i => ++i);
+[1, 2, 3].map(i => --i);
+
+// no error
+[1, 2, 3].map(i => i + 1);
+[1, 2, 3].map(i => i - 1);
